import {  ChangeDetectionStrategy,  ChangeDetectorRef,  Component,  ElementRef,  EventEmitter,  HostListener,  Input,  OnInit,  Output,} from '@angular/core';import { FormGroup } from '@angular/forms';import { LocationComponent, MultiRegionData } from '@shared/components/location/location.component';import { FilterType, IFilterV2 } from '../filter.model';import { IPresetFilters } from "@core/services/api/model/preset.model";export enum FilterDisplay {  BOTH = 'BOTH',  STORIES = 'STORIES',  CASES = 'CASES',}@Component({  selector: 'loop-filter-dropdown',  templateUrl: './filter-dropdown.component.html',  styleUrls: ['./filter-dropdown.component.scss'],  changeDetection: ChangeDetectionStrategy.OnPush,})export class FilterDropdownComponent implements OnInit {  protected readonly location = location;  protected readonly LocationComponent = LocationComponent;  @Input() config: IFilterV2<any>;  @Input() form: FormGroup;  @Input() internalName: any;  @Input() data: any;  @Input() isModal: boolean;  @Input() lastRegionId: string;  @Input() isCases: boolean;  @Input() selectedFilterTitle: string;  @Input() resetFiltersEvent: EventEmitter<void>;  @Output() confirm = new EventEmitter<boolean>();  @Output() regionIdChanged = new EventEmitter<number>();  @Output() escapeClicked = new EventEmitter<Event>();  applyVisible = true;  currentFiltersCount = 0;  FilterType = FilterType;  constructor(private cd: ChangeDetectorRef, private el: ElementRef) {}  ngOnInit(): void {    this.resetFiltersEvent?.subscribe(() => {      this.resetCurrentFilters();    });    if (this.config.type === this.FilterType.ORGANISATION) {      this.data = this.form.get('organisation')?.value || [];      this.form.get('organisation')?.valueChanges.subscribe();    }    if (this.config.type === this.FilterType.REGION      || this.config.type === this.FilterType.ORGANISATION      || this.config.type === this.FilterType.PRESET) {      this.applyVisible = false;    }    if (this.config.type === this.FilterType.REGION) {      this.data = this.form.get('region')?.value || [];      this.form.get('region')?.valueChanges.subscribe((regionData: MultiRegionData) => {        this.data = regionData;        this.cd.detectChanges();      });    }    this.regionIdChanged.subscribe(() => {      this.onFiltersApply();    });  }  onFiltersApply(): void {    this.confirm.emit();  }  totalSelectedChange(count: number): void {    this.updateTotalCount(count);  }  applyButtonVisibilityChange(visible: boolean): void {    this.applyVisible = visible;    this.cd.markForCheck();  }  updateTotalCount(count: number): void {    this.currentFiltersCount = count;    this.cd.detectChanges();  }  resetCurrentFilters(): void {    if (Array.isArray(this.config?.data)) {      this.config.data.forEach((item) => {        if (Array.isArray(item.data)) {          item.data.forEach((nestedItem) => {            nestedItem.checked = false;          });        } else if (item.selected !== undefined) {          item.selected = false;        }      });    } else if (Array.isArray(this.config?.data?.data)) {      this.config.data.data.forEach((item) => {        item.checked = false;      });    }    if (this.config?.filterFormConfig) {      Object.keys(this.config.filterFormConfig).forEach((key) => {        const control = this.form.get(key);        if (control) {          control.reset();        }      });    }    this.updateTotalCount(0);    this.cd.detectChanges();  }  processButtonVisibility(): void {    this.applyButtonVisibilityChange(this.currentFiltersCount > 0);  }  handleBlurApplyBtn(event: Event): void {    event.stopImmediatePropagation();    event.preventDefault();    switch (this.config.type) {      case FilterType.CHECKBOX_TABS:      case FilterType.CALENDAR:        const matTabs: HTMLCollectionOf<Element> = document.getElementsByClassName('mat-tab-label');        const activeIndex = Array.from(matTabs).findIndex((tab) => tab.classList.contains('mat-tab-label-active'));        (matTabs[activeIndex + 1] as HTMLElement)?.focus();        break;      case FilterType.CHECKBOX_LIST:        ((this.el.nativeElement?.getElementsByClassName('thematic-back__btn')?.[0] as HTMLElement)?.children?.[0] as HTMLElement)?.focus();        break;      default:        break;    }  }  @HostListener('document:keydown.escape', ['$event'])  onEscapePress(event: KeyboardEvent): void {    this.escapeClicked.emit(event);  }  onOrganisationsChange(organisationIds: string[]): void {    const control = this.form.get('organisation');    if (control) {      const currentValue = control.value || [];      if (JSON.stringify(currentValue) !== JSON.stringify(organisationIds)) {        control.setValue(organisationIds, {emitEvent: false});      }    }    this.onFiltersApply();  }  onLocationsChange(regionData: MultiRegionData | any): void {    const { apply, ...cleanRegionData } = regionData;    const control = this.form.get('region');    if (control) {      control.setValue(cleanRegionData, { emitEvent: false });    }    if (apply) {      this.onFiltersApply();    }  }  closeDropdown(): void {    this.applyVisible = false;    this.cd.detectChanges();  }  onPresetApplied(filters: IPresetFilters): void {    this.form.patchValue(filters);    this.onFiltersApply();  }}