import { ChangeDetectionStrategy, Component, Injector, Input } from '@angular/core';import { NgControl, UntypedFormControl } from '@angular/forms';import { InputComponent } from '@shared/components/input/input.component';import { ControlValueAccessorBase } from '@shared/utils/control-value-accessor-base';@Component({  selector: 'loop-length-filter',  templateUrl: './length-filter.component.html',  styleUrls: ['./length-filter.component.scss'],  changeDetection: ChangeDetectionStrategy.OnPush,})export class LengthFilterComponent extends ControlValueAccessorBase<{ min: number; max: number }> {  @Input() isModal: boolean;  maxAvailableValue = 3600;  minControl = new UntypedFormControl(null);  maxControl = new UntypedFormControl(null);  protected readonly Number = Number;  get min(): number {    return this.minControl.value;  }  get max(): number {    return this.maxControl.value;  }  constructor(protected ngControl: NgControl, protected injector: Injector) {    super(ngControl, injector);  }  writeValue(obj: { min: number; max: number }) {    super.writeValue(obj);    this.minControl.setValue(obj?.min >= 0 ? obj.min : null);    this.maxControl.setValue(obj?.max >= 0 ? obj.max : null);  }  onValueChange(input: InputComponent, property: string): void {    const lastValue = { min: this.min, max: this.max };    if (input.value === '') {      this.emitValue({ ...lastValue, [property]: null });      return;    }    let newValue = Number(input.value);    // Check maxAvailable value    newValue = newValue > this.maxAvailableValue ? this.maxAvailableValue : newValue;    // If new value negative    if (newValue < 0) {      this.emitValue({ ...lastValue, [property]: property === 'max' ? this.min || 0 : 0 });      return;    }    if (property === 'min') {      const max = lastValue.max || 0;      this.emitValue({ ...lastValue, [property]: max === 0 || newValue <= max ? newValue : max });    } else {      const min = lastValue.min || 0;      this.emitValue({ ...lastValue, [property]: min === 0 || newValue >= min ? newValue : min });    }  }  onClearClicked(): void {    this.minControl.setValue(null);    this.maxControl.setValue(null);    this.onChange(null);  }  private emitValue({ min, max }: { min: number; max: number }): void {    min >= 0 && this.minControl.setValue(min);    max >= 0 && this.maxControl.setValue(max);    this.onChange({      ...(min !== null && min >= 0 && { min }),      ...(max !== null && max >= 0 && { max }),    });  }}